import{chromium}from'@playwright/test';import{readFile,writeFile}from'node:fs/promises';const f=JSON.parse(await readFile('/var/folders/8c/_1mbhvpn6jj56rmbk2q8rqfc0000gn/T/atlas-prod-control-28bp5huw/production-smoke-fixture.private.json','utf8'));const b=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'}),c=await b.newContext({viewport:{width:1440,height:1000}}),old='https://d1derxijdb4l2v.cloudfront.net';await c.addCookies([{name:'ald_session',value:f.token,url:old,secure:true,httpOnly:true,sameSite:'Strict'},{name:'ald_csrf',value:f.csrf,url:old,secure:true,sameSite:'Strict'}]);const p=await c.newPage(),hosts=[],errors=[];p.on('framenavigated',frame=>{if(frame===p.mainFrame())hosts.push(new URL(frame.url()).origin)});p.on('pageerror',e=>errors.push(e.message));try{await p.goto(f.hub);await p.getByText('Latest link',{exact:true}).waitFor({timeout:45000});const account=await p.evaluate(async()=>await(await fetch('/api/session')).json());if(account.user?.id!==f.id)throw Error('Transferred account identity mismatch');const cookies=await c.cookies(f.hub);if(!cookies.some(x=>x.name==='ald_session'&&x.httpOnly&&x.secure))throw Error('Destination session cookie missing');await p.screenshot({path:'evidence/production-rollout-20261021/browser/11-old-hub-session-restored.png',fullPage:true});const result={result:'PASS',task:'Actual old Hub host-only session transfers to new Hub through browser-bound single-use handoff',source:old,destination:f.hub,visitedOrigins:hosts,destinationSessionCookie:true,accountIdentityPreserved:true,errors};await writeFile('evidence/production-rollout-20261021/HUB_SESSION_TRANSFER_VERIFICATION.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result))}catch(e){await p.screenshot({path:'evidence/production-rollout-20261021/browser/hub-transfer-failure.png',fullPage:true});await writeFile('evidence/production-rollout-20261021/HUB_SESSION_TRANSFER_VERIFICATION.json',JSON.stringify({result:'FAIL',message:e.message,visitedOrigins:hosts,errors},null,2));console.error(e.message);process.exitCode=1}finally{await b.close()}
